#!/bin/sh
# Regenerate compiler/src/runtime_c.trk from runtime/track_runtime.c.
#
# The self-hosted compiler writes the runtime next to every program it
# builds, so it carries the C source as Track string literals together with
# the prototype and arity of each exported function.
#
#   scripts/embed_runtime.sh          # rewrite the generated file
#   scripts/embed_runtime.sh --check  # fail if it is out of date
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
src="$root/runtime/track_runtime.c"
out="$root/compiler/src/runtime_c.trk"
tmp="${out}.tmp.$$"

awk '
function esc(s) {
    gsub(/\\/, "\\\\", s)
    gsub(/"/, "\\\"", s)
    return s
}
BEGIN {
    print "// runtime_c.trk — GENERATED by scripts/embed_runtime.sh from"
    print "// runtime/track_runtime.c. Do not edit by hand."
    print ""
    print "import \"base\";"
    print ""
    print "fn runtime_source(b: i64) -> i64 {"
}
{
    lines[NR] = $0
    print "    sb_line(b, \"" esc($0) "\");"
    if ($0 ~ /^tk_w [a-z_0-9]+\([^)]*\) \{/) {
        name = $0
        sub(/^tk_w /, "", name)
        sub(/\(.*/, "", name)
        params = $0
        sub(/^[^(]*\(/, "", params)
        sub(/\).*/, "", params)
        if (params == "void") {
            arity = 0
        } else {
            arity = gsub(/,/, ",", params) + 1
        }
        nfn++
        fname[nfn] = name
        farity[nfn] = arity
    }
}
END {
    print "    return 0;"
    print "}"
    print ""
    print "// Prototypes of every runtime function, for generated programs."
    print "fn runtime_prototypes(b: i64) -> i64 {"
    for (i = 1; i <= nfn; i++) {
        p = ""
        for (j = 0; j < farity[i]; j++) {
            p = p (j > 0 ? ", " : "") "tk_w"
        }
        if (p == "") p = "void"
        print "    sb_line(b, \"tk_w " fname[i] "(" p ");\");"
    }
    print "    return 0;"
    print "}"
    print ""
    print "// Record the arity of every runtime function (NI_EXTERN)."
    print "fn register_runtime(c: i64) -> i64 {"
    for (i = 1; i <= nfn; i++) {
        print "    ni_set(c, intern(c, \"" fname[i] "\"), NI_EXTERN, " farity[i] ");"
    }
    print "    return 0;"
    print "}"
}
' "$src" > "$tmp"

if [ "${1:-}" = "--check" ]; then
    if cmp -s "$tmp" "$out"; then
        rm -f "$tmp"
        echo "runtime_c.trk is up to date"
        exit 0
    fi
    rm -f "$tmp"
    echo "compiler/src/runtime_c.trk is stale; run scripts/embed_runtime.sh" >&2
    exit 1
fi
mv "$tmp" "$out"
echo "wrote $out"
